                            unit_.plan_slots[bsp::kPilotSlotThrottle].active = 1;
                            unit_.plan_slots[bsp::kPilotSlotAirBrake].desired = gth.air_brake_2a8;
                            unit_.plan_slots[bsp::kPilotSlotAirBrake].active = 1;
