                            cin.timer_550 = unit_.torpedo_closetoship_timer_550;
                            cin.latch_43c = unit_.torpedo_closetoship_latch_43c;
                            cin.mode_370 =
                                static_cast<int>(unit_.torpedo_attack_mode_370);
