                        in.sector_probe_enabled_aa = ap.no_clear_sector_aa != 0;
                        in.has_ordnance_132 = ap.has_ordnance_132;
                        in.elapsed_134 = ap.elapsed_134;
                        in.speed_late_7c = ap.speed_late_7c;
                        in.speed_early_80 = ap.speed_early_80;
