                                    const float ae = e > 0.0f ? e : 0.0f - e;
                                    const float as = spd > 0.0f ? spd : 0.0f - spd;
                                    const float ratio = tin.desired_speed / as;
                                    const bool apply = static_cast<double>(ae) > 0.8333333134651184
                                        || 1.0f > spd || ratio > 1.5f || 0.5f > ratio;
